from api import submit

def test_default_batch_size():
    # Test that default batch_size=20 is used when not provided
    def mock_enqueue(data):
        print(f"Enqueue called with: {data}")
        return data

    result = submit("user1", mock_enqueue)
    assert result == {"owner": "user1", "batch_size": 20}, f"Expected default batch_size=20, got {result}"


def test_batch_size_in_range():
    # Test valid integer values between 1 and 100
    def mock_enqueue(data):
        print(f"Enqueue called with: {data}")
        return data

    for bs in [1, 50, 100]:
        result = submit("user2", mock_enqueue, batch_size=bs)
        assert result == {"owner": "user2", "batch_size": bs}, f"Invalid batch_size={bs}", f"Got {result}"


def test_batch_size_rejects_bool():
    # Test that boolean is rejected
    def mock_enqueue(data):
        print(f"Enqueue called with: {data}")
        return data

    try:
        submit("user3", mock_enqueue, batch_size=True)
        assert False, "Should have raised ValueError for boolean batch_size"
    except ValueError as e:
        assert "batch_size" in str(e), f"Expected error message about batch_size, got: {e}"


def test_batch_size_rejects_non_integer():
    # Test that non-integer values are rejected
    def mock_enqueue(data):
        print(f"Enqueue called with: {data}")
        return data

    invalid_values = [3.14, "invalid", None, [], {}]
    for val in invalid_values:
        try:
            submit("user4", mock_enqueue, batch_size=val)
            assert False, f"Should have raised ValueError for batch_size={val}"
        except ValueError as e:
            assert "batch_size" in str(e), f"Expected error message about batch_size, got: {e}"


def test_batch_size_rejects_out_of_range():
    # Test values outside 1..100 range are rejected
    def mock_enqueue(data):
