            assert False, f"Should have raised ValueError for batch_size={val}"
        except ValueError as e:
            assert "batch_size" in str(e), f"Expected error message about batch_size, got: {e}"


def test_preserves_owner():
    # Test that owner is preserved in payload
    def mock_enqueue(data):
        print(f"Enqueue called with: {data}")
        return data

    result = submit("my_user", mock_enqueue, batch_size=50)
    assert result["owner"] == "my_user", f"Owner not preserved: {result}"


