from queueing import payload

def submit(owner, enqueue, batch_size=20):
    if isinstance(batch_size, bool):
        raise ValueError("batch_size must not be a boolean type")
    if not isinstance(batch_size, int):
        raise ValueError(f"batch_size must be an integer, got {type(batch_size).__name__}")
    if batch_size < 1 or batch_size > 100:
        raise ValueError(f"batch_size must be between 1 and 100, got {batch_size}")

    payload_data = payload(owner)
    if batch_size is not None:
        payload_data["batch_size"] = batch_size
    return enqueue(payload_data)

